import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { JSDOM } from "jsdom";
import { makeApiMock } from "./apiMock.js";

const DIR = path.dirname(fileURLToPath(import.meta.url));

export async function montarApp(opts = {}) {
  const [html, appjs] = await Promise.all([
    readFile(path.join(DIR, "..", "public", "index.html"), "utf8"),
    readFile(path.join(DIR, "..", "public", "app.js"), "utf8"),
  ]);

  const mock = makeApiMock(opts);

  const dom = new JSDOM(html, {
    url: "http://localhost/",
    runScripts: "dangerously",
    beforeParse(window) {
      window.fetch = mock.fetchImpl;
    },
  });

  dom.window.eval(appjs);

  return { dom, window: dom.window, mock, app: dom.window.M3 };
}

export async function esperar(ms = 10) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function enviarSubmit(window, seletorFormulario) {
  const form = window.document.querySelector(seletorFormulario);
  form.dispatchEvent(new window.Event("submit", { bubbles: true, cancelable: true }));
}

export async function preencherEEnviar(window, { encontroId, codigo, form }) {
  window.document.querySelector(`${form} [name="encontroId"]`).value = encontroId;
  if (codigo !== undefined) window.document.querySelector(`${form} [name="codigo"]`).value = codigo;
  enviarSubmit(window, form);
  await esperar();
}
