export const JANELA = 60000;
const ALFABETO = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

function hashStr(s) {
  let h = 2166136261;
  for (const c of s) {
    h ^= c.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function codigoDaJanela(encontroId, janelaInicio) {
  let codigo = "";
  for (let i = 0; i < 6; i++) {
    const h = hashStr(`${encontroId}|${janelaInicio}#${i}`);
    codigo += ALFABETO[h % ALFABETO.length];
  }
  return codigo;
}

export function makeApiMock(opts = {}) {
  const estado = {
    agora: opts.agora ? Date.parse(opts.agora) : Date.now(),
    semRede: false,
    erroCodigo: null,
    erroPresenca: null,
    requisicoes: { codigos: [], presencas: [] },
  };

  function codigoAtual(encontroId) {
    const janela = Math.floor(estado.agora / JANELA) * JANELA;
    return codigoDaJanela(encontroId, janela);
  }

  function responder(status, dados) {
    return {
      ok: status < 400,
      status,
      statusText: String(status),
      headers: new Headers({ "Content-Type": "application/json" }),
      async text() { return JSON.stringify(dados); },
    };
  }

  async function fetchImpl(url, opcoes = {}) {
    if (estado.semRede) throw new TypeError("Failed to fetch");
    const u = new URL(String(url));
    const metodo = (opcoes.method || "GET").toUpperCase();
    const cabecalhos = opcoes.headers || {};
    const usuario = cabecalhos["X-Usuario"];
    const corpo = opcoes.body ? JSON.parse(opcoes.body) : undefined;

    const mLegivel = u.pathname.match(/^\/encontros\/([^/]+)\/codigo$/);
    const mRegistro = u.pathname.match(/^\/encontros\/([^/]+)\/presencas$/);

    if (mLegivel && metodo === "GET") {
      estado.requisicoes.codigos.push({ encontroId: mLegivel[1], usuario });
      if (estado.erroCodigo) return responder(estado.erroCodigo.status, estado.erroCodigo);
      const janela = Math.floor(estado.agora / JANELA) * JANELA;
      return responder(200, {
        encontroId: mLegivel[1],
        codigo: codigoDaJanela(mLegivel[1], janela),
        trocaEm: new Date(janela + JANELA).toISOString(),
        validoAte: new Date(janela + 2 * JANELA).toISOString(),
      });
    }

    if (mRegistro && metodo === "POST") {
      estado.requisicoes.presencas.push({ encontroId: mRegistro[1], usuario, corpo });
      if (estado.erroPresenca) return responder(estado.erroPresenca.status, estado.erroPresenca);
      const offline = typeof corpo.lidoEm === "string";
      const registradaEm = new Date(estado.agora).toISOString();
      return responder(201, {
        id: "pre_mock00000001",
        encontroId: mRegistro[1],
        participanteId: usuario,
        origem: offline ? "qr_offline" : "qr",
        lidoEm: offline ? corpo.lidoEm : registradaEm,
        registradaEm,
        justificativa: null,
      });
    }

    return responder(404, { erro: "NAO_ENCONTRADO", mensagem: "rota inexistente no mock" });
  }

  return {
    estado,
    codigoAtual,
    codigoDaJanela,
    fetchImpl,
    setAgora(iso) { estado.agora = Date.parse(iso); },
    avancarSegundos(s) { estado.agora += s * 1000; },
  };
}

import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { JSDOM } from "jsdom";
import { makeApiMock } from "./apiMock.js";

const DIR = path.dirname(fileURLToPath(import.meta.url));

export async function montarApp(opts = {}) {
  const [html, appjs] = await Promise.all([
    readFile(path.join(DIR, "..", "public", "index.html"), "utf8"),
    readFile(path.join(DIR, "..", "public", "app.js"), "utf8"),
  ]);

  const mock = makeApiMock(opts);

  const dom = new JSDOM(html, {
    url: "http://localhost/",
    runScripts: "dangerously",
    beforeParse(window) {
      window.fetch = mock.fetchImpl;
    },
  });

  dom.window.eval(appjs);
  if (!dom.window.M3.foiIniciado()) dom.window.M3.iniciar();

  return { dom, local: dom.window, mock, app: dom.window.M3 };
}

export async function esperar(ms = 10) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function comApp(opts, fn) {
  const { dom, local, mock, app } = await montarApp(opts);
  try {
    return await fn({ dom, local, mock, app });
  } finally {
    app.desligar();
    dom.window.close();
  }
}

export function enviarSubmit(local, seletorFormulario) {
  const form = local.document.querySelector(seletorFormulario);
  form.dispatchEvent(new local.Event("submit", { bubbles: true, cancelable: true }));
}

export async function preencherEEnviar(local, { encontroId, codigo, form }) {
  local.document.querySelector(`${form} [name="encontroId"]`).value = encontroId;
  if (codigo !== undefined) {
    local.document.querySelector(`${form} [name="codigo"]`).value = codigo;
  }
  enviarSubmit(local, form);
  await esperar();
}

export function formatarInstanteLocal(iso) {
  return new Date(iso).toLocaleTimeString("pt-BR", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { comApp, esperar, enviarSubmit, formatarInstanteLocal } from "./apoio.js";
import { JANELA } from "./apiMock.js";

describe("Tela da organização", () => {
  it("exibe o código do encontro, trocaEm e validoAte retornados pela API", async () => {
    await comApp({ agora: "2026-10-19T10:15:30-03:00" }, async ({ local, mock }) => {
      local.document.querySelector("#org-encontro-id").value = "enc_5e6f7a8b";
      enviarSubmit(local, "#org-form");
      await esperar();

      const codigo = mock.codigoAtual("enc_5e6f7a8b");
      assert.match(codigo, /^[A-Z0-9]{6}$/);

      const box = local.document.getElementById("org-codigo-box");
      assert.equal(box.hidden, false);
      assert.equal(local.document.getElementById("org-codigo").textContent, codigo);
      assert.equal(local.document.getElementById("org-encontro-info").textContent, "enc_5e6f7a8b");
      assert.equal(
        local.document.getElementById("org-troca").textContent,
        formatarInstanteLocal(new Date(mock.estado.agora + JANELA).toISOString())
      );
      assert.equal(
        local.document.getElementById("org-valido").dateTime,
        new Date(mock.estado.agora + 2 * JANELA).toISOString()
      );
      assert.equal(
        local.document.getElementById("org-troca").dateTime,
        new Date(mock.estado.agora + JANELA).toISOString()
      );

      const chamada = mock.estado.requisicoes.codigos[0];
      assert.equal(chamada.encontroId, "enc_5e6f7a8b");
      assert.equal(chamada.usuario, "org-ana");
    });
  });

  it("atualiza o código automaticamente quando chega a rotação e reagenda a próxima", async () => {
    await comApp({ agora: "2026-10-19T10:15:30-03:00" }, async ({ local, mock, app }) => {
      local.document.querySelector("#org-encontro-id").value = "enc_5e6f7a8b";
      enviarSubmit(local, "#org-form");
      await esperar();

      const antes = local.document.getElementById("org-codigo").textContent;
      assert.equal(app.organizacao.temAgendamento(), true);

      mock.avancarSegundos(60);
      await app.organizacao.rotacaoAtingida();
      await esperar();

      const depois = local.document.getElementById("org-codigo").textContent;
      assert.notEqual(depois, antes);
      assert.equal(depois, mock.codigoAtual("enc_5e6f7a8b"));
      assert.equal(app.organizacao.temAgendamento(), true);
    });
  });

  it("trata FORA_DA_JANELA retornando pela API", async () => {
    await comApp({ agora: "2026-10-19T10:15:30-03:00" }, async ({ local, mock, app }) => {
      mock.estado.erroCodigo = {
        status: 422,
        erro: "FORA_DA_JANELA",
        mensagem: "Fora da janela de obtenção do código",
      };
      local.document.querySelector("#org-encontro-id").value = "enc_5e6f7a8b";
      enviarSubmit(local, "#org-form");
      await esperar();

      const msg = local.document.getElementById("org-msg");
      assert.ok(msg.className.includes("erro"));
      assert.ok(msg.textContent.includes("FORA_DA_JANELA"));
      assert.equal(local.document.getElementById("org-codigo-box").hidden, true);
      assert.equal(app.organizacao.temAgendamento(), false);
    });
  });

  it("trata ATIVIDADE_CANCELADA retornando pela API", async () => {
    await comApp({ agora: "2026-10-19T10:15:30-03:00" }, async ({ local, mock }) => {
      mock.estado.erroCodigo = {
        status: 422,
        erro: "ATIVIDADE_CANCELADA",
        mensagem: "A atividade foi cancelada",
      };
      local.document.querySelector("#org-encontro-id").value = "enc_5e6f7a8b";
      enviarSubmit(local, "#org-form");
      await esperar();

      const msg = local.document.getElementById("org-msg");
      assert.ok(msg.className.includes("erro"));
      assert.ok(msg.textContent.includes("ATIVIDADE_CANCELADA"));
      assert.equal(local.document.getElementById("org-codigo-box").hidden, true);
    });
  });

  it("sem conexão mantém código exibido e agenda nova tentativa", async () => {
    await comApp({ agora: "2026-10-19T10:15:30-03:00" }, async ({ local, mock, app }) => {
      local.document.querySelector("#org-encontro-id").value = "enc_5e6f7a8b";
      enviarSubmit(local, "#org-form");
      await esperar();
      const primeiro = local.document.getElementById("org-codigo").textContent;

      mock.estado.semRede = true;
      mock.avancarSegundos(60);
      await app.organizacao.rotacaoAtingida();
      await esperar();

      const msg = local.document.getElementById("org-msg");
      assert.ok(msg.className.includes("aviso"));
      assert.ok(msg.textContent.includes("Sem conexão"));
      assert.equal(local.document.getElementById("org-codigo").textContent, primeiro);
      assert.equal(app.organizacao.temAgendamento(), true);
    });
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { comApp, preencherEEnviar } from "./apoio.js";

describe("Tela do participante", () => {
  it("envia o código digitado e mostra sucesso quando a API aceita", async () => {
